import{_ as e,c as a,o,V as i,cQ as s}from"./chunks/framework.tJhZUYt7.js";const b=JSON.parse('{"title":"二、组件解析","description":"","frontmatter":{},"headers":[],"relativePath":"rear/java/Java开发框架/SpringMVC/组件解析.md","filePath":"rear/java/Java开发框架/SpringMVC/组件解析.md","lastUpdated":1719821588000}'),t={name:"rear/java/Java开发框架/SpringMVC/组件解析.md"},l=i('<h1 id="二、组件解析" tabindex="-1">二、组件解析 <a class="header-anchor" href="#二、组件解析" aria-label="Permalink to &quot;二、组件解析&quot;">​</a></h1><h2 id="一、springmvc的执行流程" tabindex="-1">一、SpringMVC的执行流程 <a class="header-anchor" href="#一、springmvc的执行流程" aria-label="Permalink to &quot;一、SpringMVC的执行流程&quot;">​</a></h2><img src="'+s+`"><div class="info custom-block"><p class="custom-block-title">执行流程</p><ol><li>用户发送请求至前端控制器<code>DispatcherServlet</code></li><li><code>DispatcherServet</code>收到请求调用<code>HandlerMapping</code>处理器映射器</li><li>处理器映射器找到具体的处理器(可以根据<code>xml</code>配置、注解进行查找)，生成处理器对象及处理器拦截器(如果有则生成)一并返回给<code>DispatcherServlet</code></li><li><code>DispatcherServlet</code>调用<code>HanderAdapter</code>处理器适配器。</li><li><code>HandlerAdapter</code>经过适配调用具体的处理器(<code>Controller</code>，也叫后端控制器)。</li><li><code>Controler</code>执行完成返回<code>ModelAndView</code></li><li><code>HandlerAdapter</code>将<code>controller</code>执行结果<code>ModelAndView</code>返回给<code>DispatcherServlet</code></li><li><code>DispatcherServlet</code>将<code>ModelAndView</code>传给<code>ViewReslover</code>视图解析器。</li><li><code>ViewReslover</code>解析后返回具体<code>View</code>。</li><li><code>DispatcherServlet</code>根据View进行渲染视图(即将模型数据填充至视图中)。<code>DispatcherServlet</code>响应用户</li></ol></div><h2 id="二、注解解析" tabindex="-1">二、注解解析 <a class="header-anchor" href="#二、注解解析" aria-label="Permalink to &quot;二、注解解析&quot;">​</a></h2><h3 id="_1、-requestmapping" tabindex="-1">1、@RequestMapping <a class="header-anchor" href="#_1、-requestmapping" aria-label="Permalink to &quot;1、@RequestMapping&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">介绍</p><p>作用：用于建立请求URL和处理请求方法之间的对应关系</p><p>位置：</p><ul><li>类上，请求URL的第一级访问目录。此处不写的话，就相当于应用的根目录</li><li>方法上，请求URL的第二级访问目录，与类上的使用<code>@RequestMapping</code>标注的一级目录一起组成访问虚拟路径</li></ul><p>属性:</p><ul><li><p><code>value</code>:用于指定请求的URL。它和path属性的作用是一样的</p></li><li><p><code>method</code>:用于指定请求的方式</p></li><li><p><code>params</code>:用于指定限制请求参数的条件。它支持简单的表达式。要求请求参数的key和value必须和配置的一模一样</p><p>例如:</p><ul><li>params={&quot;accountName&quot;}，表示请求参数必须有accountName</li><li>params={&quot;moeny!100&quot;}，表示请求参数中money不能是100</li></ul></li></ul></div><h2 id="三、xml配置解析" tabindex="-1">三、XML配置解析 <a class="header-anchor" href="#三、xml配置解析" aria-label="Permalink to &quot;三、XML配置解析&quot;">​</a></h2><h3 id="_1、视图解析器" tabindex="-1">1、视图解析器 <a class="header-anchor" href="#_1、视图解析器" aria-label="Permalink to &quot;1、视图解析器&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">信息</p><p><code>SpringMVC</code>有默认组件配置，默认组件都是<code>DispatcherServlet.properties</code>配置文件中配置的，该配置文件地址<code>org/springframework/web/servlet/DispatcherServlet.properties</code>该文件中配置了默认的视图解析器，如下</p></div><div class="language-xml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">org.springframework.web.servlet.ViewResolver=org.springframework.web.servlet.view.InternalResourceViewResolver</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>翻看该解析器源码，可以看到该解析器的默认设置，如下:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>REDIRECT_URL_PREFIX = &quot;redirect:&quot;			--重定向前缀</span></span>
<span class="line"><span>FORWARD_URL_PREEIX = &quot;forward:&quot;				--转发前缀(默认值)</span></span>
<span class="line"><span>prefix = &quot;;								   --视图名称前缀</span></span>
<span class="line"><span>suffix = &quot;&quot;;						    	--视图名称后缀</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div>`,13),r=[l];function c(n,d,p,u,h,m){return o(),a("div",null,r)}const _=e(t,[["render",c]]);export{b as __pageData,_ as default};
